"""Knot-preserving common station rows for ordinary and paired Section curves.

The common parameter t is normalized control rank, not native arc length.
``arc_factor`` maps it piecewise linearly between the selected curve's actual
control-knot arc-length factors. All original control ranks from both members
are mandatory rows. Each interval is subdivided for the longer physical member
interval, so both members have exactly the same longitudinal row allocation.
"""

MAX_ROWS = 16384
MAX_CONTROLS = 512
KNOT_MERGE_DISTANCE = 1e-6


def _selected_curve(g, curves, path_index, label):
    index = g.node('GeometryNodeInputIndex', label + ' curve index').outputs[0]
    separate = g.node('GeometryNodeSeparateGeometry', label + ' selected complete Section curve')
    separate.domain = 'CURVE'
    g.set(curves, separate.inputs['Geometry'])
    g.set(g.compare(index, path_index, 'EQUAL', 'INT'), separate.inputs['Selection'])
    selected = separate.outputs['Selection']
    size = g.node('GeometryNodeAttributeDomainSize', label + ' authored control count')
    size.component = 'CURVE'
    g.set(selected, size.inputs['Geometry'])
    length = g.node('GeometryNodeCurveLength', label + ' evaluated arc length')
    g.set(selected, length.inputs['Curve'])
    valid = g.all(g.compare(size.outputs['Spline Count'], 1, 'EQUAL', 'INT'),
                  g.compare(size.outputs['Point Count'], 2, 'GREATER_EQUAL', 'INT'))
    return selected, size.outputs['Point Count'], length.outputs['Length'], valid


def _factor(g, selected, count, t):
    """The selected curve has local control indices 0 through count-1."""
    bounded_t = g.math('MAXIMUM', 0., g.math('MINIMUM', 1., t))
    rank = g.math('MULTIPLY', bounded_t, g.math('SUBTRACT', count, 1.))
    low = g.math('FLOOR', rank)
    high = g.math('MINIMUM', g.math('ADD', low, 1.), g.math('SUBTRACT', count, 1.))
    blend = g.math('SUBTRACT', rank, low)
    parameter = g.node('GeometryNodeSplineParameter', 'Evaluated arc-length factor at authored control knots')
    first = g.sample(selected, parameter.outputs['Factor'], low, 'FLOAT')
    second = g.sample(selected, parameter.outputs['Factor'], high, 'FLOAT')
    return g.math('ADD', first, g.math('MULTIPLY', blend, g.math('SUBTRACT', second, first)))


def arc_factor(g, curves, path_index, t):
    """Map common control-rank t to the selected path's native arc factor.

Pass ``1-t`` for a partner whose authored direction opposes the current path.
The caller owns index validity; ``construct`` checks both selected paths.
"""
    selected, count, _length, _valid = _selected_curve(g, curves, path_index, 'Arc mapping')
    return _factor(g, selected, count, t)


def sampled_rank(g, selected, count, t, label):
    """Recover cubic parameter while preserving the known control-knot identity.

    At an authored knot, an arc-factor lookup followed by Sample Curve may
    return a value just inside the preceding span. The known normalized control
    rank is the authority there, not that lossy round trip. Frames and chord
    certificates must use exactly the same convention.
    """
    parameter = g.node('GeometryNodeSampleCurve', label)
    parameter.data_type = 'FLOAT'; parameter.mode = 'FACTOR'
    g.set(selected, parameter.inputs['Curves'])
    g.set(_factor(g, selected, count, t), parameter.inputs['Factor'])
    g.set(g.named('st_knot_index', 'FLOAT'), parameter.inputs['Value'])
    count_last = g.math('SUBTRACT', count, 1.)
    bounded = g.math('MAXIMUM', 0., g.math('MINIMUM', 1., t))
    logical = g.math('MULTIPLY', bounded, count_last)
    nearest = g.math('ROUND', logical)
    direct = g.math('DIVIDE', nearest, count_last)
    reversed_rank = g.math('SUBTRACT', 1., g.math('DIVIDE',
        g.math('SUBTRACT', count_last, nearest), count_last))
    round_trip = g.math('SUBTRACT', 1., g.math('SUBTRACT', 1., direct))
    # These are the encodings used by the mandatory-knot constructor and its
    # canonical member ordering (which can reverse the parameter twice).
    # Exact equality avoids snapping a merely nearby interior sample. A fixed
    # epsilon on logical rank is unreliable for long, reversed control lists.
    knot = g.either(g.close(bounded, direct, 0.), g.close(bounded, reversed_rank, 0.))
    knot = g.either(knot, g.close(bounded, round_trip, 0.))
    rank = g.switch(knot, parameter.outputs['Value'], nearest)
    rank = g.math('MAXIMUM', 0., g.math('MINIMUM', rank, count_last))
    return parameter, rank


def evaluated_frame(g, curves, path_index, t, *, preserve_knots=False):
    """Return analytic cubic position/right-normal or exact POLY/miter frame.

Blender's Sample Curve tangent comes from the evaluated approximation and can
noticeably rotate a wide profile. A FLOAT sample of the original st_knot_index
instead gives segment index plus local Bezier parameter. Evaluate the cubic
polynomial and its derivative directly at that parameter. This preserves exact
waypoints and analytic profile orientation while retaining native arc stationing.
The selected spline carries st_sweep_interpolation on CURVE and, in exact mode,
st_poly_miter on POINT as prepared by the Section path constructor.
"""
    selected, count, _length, _valid = _selected_curve(g, curves, path_index, 'Analytic frame')
    factor = _factor(g, selected, count, t)
    parameter, rank = sampled_rank(g, selected, count, t,
        'Recover local Bezier parameter without approximate tangents')
    if not preserve_knots:
        # Ordinary sweeps have no per-span offset chord certificate. Preserve
        # their existing parameter arithmetic; only the Bundle frame must
        # share the certificate's exact authored-knot convention.
        rank = g.math('MAXIMUM', 0., g.math('MINIMUM', parameter.outputs['Value'], g.math('SUBTRACT', count, 1.)))
    segment = g.math('MINIMUM', g.math('FLOOR', rank), g.math('SUBTRACT', count, 2.))
    next_segment = g.math('ADD', segment, 1.)
    u = g.math('SUBTRACT', rank, segment)
    v = g.math('SUBTRACT', 1., u)
    position = g.node('GeometryNodeInputPosition', 'Actual cubic control positions').outputs[0]
    p0 = g.sample(selected, position, segment, 'FLOAT_VECTOR')
    p1 = g.sample(selected, g.named('st_curve_handle_right', 'FLOAT_VECTOR'), segment, 'FLOAT_VECTOR')
    p2 = g.sample(selected, g.named('st_curve_handle_left', 'FLOAT_VECTOR'), next_segment, 'FLOAT_VECTOR')
    p3 = g.sample(selected, position, next_segment, 'FLOAT_VECTOR')

    def scaled(vector, scalar):
        return g.vector('SCALE', vector, scalar)

    def add(*vectors):
        value = vectors[0]
        for vector in vectors[1:]:
            value = g.vector('ADD', value, vector)
        return value

    uu, vv, uv = g.math('MULTIPLY', u, u), g.math('MULTIPLY', v, v), g.math('MULTIPLY', u, v)
    point = add(scaled(p0, g.math('MULTIPLY', vv, v)),
                scaled(p1, g.math('MULTIPLY', 3., g.math('MULTIPLY', vv, u))),
                scaled(p2, g.math('MULTIPLY', 3., g.math('MULTIPLY', v, uu))),
                scaled(p3, g.math('MULTIPLY', uu, u)))
    derivative = scaled(add(
        scaled(g.vector('SUBTRACT', p1, p0), vv),
        scaled(g.vector('SUBTRACT', p2, p1), g.math('MULTIPLY', 2., uv)),
        scaled(g.vector('SUBTRACT', p3, p2), uu)), 3.)
    right = g.right(g.vector('NORMALIZE', derivative))
    poly_frame = g.node('GeometryNodeSampleCurve', 'Exact polyline interpolated miter frame')
    poly_frame.data_type = 'FLOAT_VECTOR'
    poly_frame.mode = 'FACTOR'
    g.set(selected, poly_frame.inputs['Curves'])
    g.set(factor, poly_frame.inputs['Factor'])
    g.set(g.named('st_poly_miter', 'FLOAT_VECTOR'), poly_frame.inputs['Value'])
    degree = g.sample(selected, g.named('st_sweep_interpolation'), 0, 'INT', 'CURVE')
    smooth = g.compare(degree, 3, 'EQUAL', 'INT')
    center = g.switch(smooth, parameter.outputs['Position'], point, 'VECTOR', 'Analytic cubic or exact polyline center')
    lateral = g.switch(smooth, poly_frame.outputs['Value'], right, 'VECTOR', 'Analytic derivative normal or exact miter')
    return center, lateral


def construct(g, curves, current_index, partner_index, reversed_pair, cell_size, *, even_intervals=False):
    """Return ``(table_mesh, row_count, valid)`` with POINT station attributes.

    st_station_t is the common rank parameter; BOOLEAN st_station_knot marks
    each mandatory rank from either member, including both terminal rows.

Use the current index as partner index for an ordinary carriageway. For paired
paths, reverse the partner parameter when ``reversed_pair`` is true. Invalid
    budgets or bindings produce a tiny two-row fallback plus ``valid=False``;
    the caller must reject the resulting surface. No large invalid Grid or station
    array is allocated before the row budget is checked.

    At most 512 controls per member keeps distinct rational control ranks more
    than 1/(511*510), approximately 3.84e-6, apart. Thus the 1e-6 merge threshold
    cannot erase a distinct mandatory knot when members have different counts.
"""
    # Both members calculate exactly the same subdivision counts, even when
    # floating-point arc lengths sit immediately beside an integer ceil
    # threshold. Only the final parameter table is reversed for the other
    # authored direction; never independently round reversed intervals.
    swapped = g.compare(current_index, partner_index, 'GREATER_THAN', 'INT')
    first_index = g.switch(swapped, current_index, partner_index, 'INT')
    second_index = g.switch(swapped, partner_index, current_index, 'INT')
    reverse_output = g.all(swapped, reversed_pair)
    current, na, length_a, valid_a = _selected_curve(g, curves, first_index, 'Canonical first')
    partner, nb, length_b, valid_b = _selected_curve(g, curves, second_index, 'Canonical second')
    controls_fit = g.all(
        g.compare(na, MAX_CONTROLS, 'LESS_EQUAL', 'INT'),
        g.compare(nb, MAX_CONTROLS, 'LESS_EQUAL', 'INT'))
    bindings_valid = g.all(valid_a, valid_b, controls_fit,
                         g.compare(cell_size, 0., 'GREATER_THAN'),
                         g.compare(length_a, 1e-5, 'GREATER_THAN'),
                         g.compare(length_b, 1e-5, 'GREATER_THAN'))
    index = g.node('GeometryNodeInputIndex', 'Station or interval index').outputs[0]
    position = g.node('GeometryNodeInputPosition', 'Mandatory knot rank coordinate').outputs[0]
    mandatory_parts = []
    for count, reverse, label in ((na, False, 'Current'), (nb, reversed_pair, 'Partner')):
        line = g.node('GeometryNodeMeshLine', label + ' mandatory authored control ranks')
        safe_count = g.switch(controls_fit, 2, count, 'INT')
        g.set(safe_count, line.inputs['Count'])
        t = g.math('DIVIDE', index, g.math('MAXIMUM', 1., g.math('SUBTRACT', safe_count, 1.)))
        if reverse is not False:
            t = g.switch(reverse, t, g.math('SUBTRACT', 1., t))
        positions = g.node('GeometryNodeSetPosition', label + ' knot ranks in common orientation')
        g.set(line.outputs['Mesh'], positions.inputs['Geometry'])
        g.set(g.xyz(t, 0., 0.), positions.inputs['Position'])
        mandatory_parts.append(positions.outputs['Geometry'])
    joined = g.node('GeometryNodeJoinGeometry', 'Union both members mandatory knot rows')
    for geometry in mandatory_parts:
        g.set(geometry, joined.inputs['Geometry'])
    merge = g.node('GeometryNodeMergeByDistance', 'Coalesce coincident common knot ranks')
    merge.inputs['Distance'].default_value = KNOT_MERGE_DISTANCE
    g.set(joined.outputs['Geometry'], merge.inputs['Geometry'])
    sort = g.node('GeometryNodeSortElements', 'Strict increasing mandatory rank order')
    sort.domain = 'POINT'
    g.set(merge.outputs['Geometry'], sort.inputs['Geometry'])
    g.set(g.component(position, 'X'), sort.inputs['Sort Weight'])
    mandatory = g.store(sort.outputs['Geometry'], 'st_station_t', g.component(position, 'X'))
    mandatory_size = g.node('GeometryNodeAttributeDomainSize', 'Unique mandatory knot count')
    mandatory_size.component = 'MESH'
    g.set(mandatory, mandatory_size.inputs['Geometry'])
    last_knot = g.math('SUBTRACT', mandatory_size.outputs['Point Count'], 1.)
    at_end = g.compare(index, last_knot, 'EQUAL', 'INT')
    t0 = g.named('st_station_t', 'FLOAT')
    t1 = g.sample(mandatory, g.named('st_station_t', 'FLOAT'),
                  g.math('MINIMUM', g.math('ADD', index, 1.), last_knot), 'FLOAT')
    a0, a1 = _factor(g, current, na, t0), _factor(g, current, na, t1)
    b0t = g.switch(reversed_pair, t0, g.math('SUBTRACT', 1., t0))
    b1t = g.switch(reversed_pair, t1, g.math('SUBTRACT', 1., t1))
    b0, b1 = _factor(g, partner, nb, b0t), _factor(g, partner, nb, b1t)
    interval_a = g.math('MULTIPLY', g.math('ABSOLUTE', g.math('SUBTRACT', a1, a0)), length_a)
    interval_b = g.math('MULTIPLY', g.math('ABSOLUTE', g.math('SUBTRACT', b1, b0)), length_b)
    required = g.math('CEIL', g.math('DIVIDE', g.math('MAXIMUM', interval_a, interval_b), cell_size))
    # Clamping an individual interval at MAX_ROWS still makes the total row
    # count exceed the permitted budget. It prevents overflowing integer sums
    # for extremely small cells while never accepting an under-sampled path.
    required = g.math('MINIMUM', MAX_ROWS, g.math('MAXIMUM', 1., required))
    steps = g.switch(at_end, required, 0, 'INT')
    records = g.store(mandatory, 'st_station_steps', steps, 'INT')
    if even_intervals is not False:
        # An all-quad disk has an even boundary-edge count. Give complete
        # independent Bundle members even interval parity before generating
        # their pavement, so a separator can close without splitting an
        # existing pavement edge or introducing a triangle. Add at most one
        # interval, on the longest sampled control span; retain every knot.
        count_steps=g.stat(records,g.named('st_station_steps'),output='Sum')
        longest=g.stat(records,g.named('st_station_steps'),output='Max')
        chosen=g.stat(records,g.switch(g.compare(g.named('st_station_steps'),longest),1e9,index),output='Min')
        extra=g.all(even_intervals,g.close(g.math('FLOORED_MODULO',count_steps,2.),1.,0.),g.compare(index,chosen))
        records=g.store(records,'st_station_steps',g.math('ADD',g.named('st_station_steps'),extra),'INT')
    accumulate = g.node('GeometryNodeAccumulateField', 'Exclusive interval row prefixes')
    accumulate.data_type = 'INT'
    accumulate.domain = 'POINT'
    g.set(g.named('st_station_steps'), accumulate.inputs['Value'])
    records = g.store(records, 'st_station_prefix', accumulate.outputs['Trailing'], 'INT')
    total = g.math('ADD', g.stat(records, g.named('st_station_steps'), output='Sum'), 1.)
    valid = g.all(bindings_valid, g.compare(total, MAX_ROWS, 'LESS_EQUAL'),
                  g.compare(mandatory_size.outputs['Point Count'], 2, 'GREATER_EQUAL', 'INT'))
    rows = g.switch(valid, 2, total, 'INT', 'Check total station budget before allocation')

    # Prefix positions enable an O(log n) nearest search rather than a repeat
    # zone or scanning every mandatory interval for each generated sample.
    lookup_positions = g.node('GeometryNodeSetPosition', 'Search interval prefixes in integer row coordinates')
    g.set(records, lookup_positions.inputs['Geometry'])
    g.set(g.xyz(g.named('st_station_prefix'), 0., 0.), lookup_positions.inputs['Position'])
    lookup = lookup_positions.outputs['Geometry']
    nearest = g.node('GeometryNodeSampleNearest', 'Locate the nearest mandatory interval prefix')
    nearest.domain = 'POINT'
    g.set(lookup, nearest.inputs['Geometry'])
    g.set(g.xyz(index, 0., 0.), nearest.inputs['Sample Position'])
    nearest_index = nearest.outputs['Index']
    nearest_prefix = g.sample(lookup, g.named('st_station_prefix'), nearest_index)
    next_prefix = g.compare(nearest_prefix, index, 'GREATER_THAN', 'INT')
    interval = g.math('MAXIMUM', 0., g.math('SUBTRACT', nearest_index, g.switch(next_prefix, 0, 1, 'INT')))
    prefix = g.sample(records, g.named('st_station_prefix'), interval)
    subdivisions = g.sample(records, g.named('st_station_steps'), interval)
    begin = g.sample(records, g.named('st_station_t', 'FLOAT'), interval, 'FLOAT')
    end = g.sample(records, g.named('st_station_t', 'FLOAT'),
                   g.math('MINIMUM', last_knot, g.math('ADD', interval, 1.)), 'FLOAT')
    blend = g.math('DIVIDE', g.math('SUBTRACT', index, prefix), g.math('MAXIMUM', 1., subdivisions))
    t = g.math('ADD', begin, g.math('MULTIPLY', blend, g.math('SUBTRACT', end, begin)))
    t = g.switch(g.compare(index, g.math('SUBTRACT', rows, 1.), 'EQUAL', 'INT'), t, 1.)
    t = g.switch(valid, index, t)
    line = g.node('GeometryNodeMeshLine', 'Allocate only the validated common station rows')
    g.set(rows, line.inputs['Count'])
    place = g.node('GeometryNodeSetPosition', 'Ordered common rank table')
    g.set(line.outputs['Mesh'], place.inputs['Geometry'])
    g.set(g.xyz(t, 0., 0.), place.inputs['Position'])
    table = g.store(place.outputs['Geometry'], 'st_station_t', t)
    knot = g.either(g.compare(index, prefix, 'EQUAL', 'INT'),
                    g.compare(index, g.math('SUBTRACT', rows, 1.), 'EQUAL', 'INT'))
    knot = g.switch(valid, True, knot, 'BOOLEAN')
    table = g.store(table, 'st_station_knot', knot, 'BOOLEAN')
    reversed_index = g.math('SUBTRACT', g.math('SUBTRACT', rows, 1.), index)
    reversed_t = g.math('SUBTRACT', 1.,
                        g.sample(table, g.named('st_station_t', 'FLOAT'), reversed_index, 'FLOAT'))
    reversed_knot = g.sample(table, g.named('st_station_knot', 'BOOLEAN'), reversed_index, 'BOOLEAN')
    local_t = g.switch(reverse_output, g.named('st_station_t', 'FLOAT'), reversed_t)
    local_knot = g.switch(reverse_output, g.named('st_station_knot', 'BOOLEAN'), reversed_knot, 'BOOLEAN')
    table = g.store(table, 'st_station_t', local_t)
    table = g.store(table, 'st_station_knot', local_knot, 'BOOLEAN')
    orient = g.node('GeometryNodeSetPosition', 'Return increasing rows in this member authored direction')
    g.set(table, orient.inputs['Geometry'])
    g.set(g.xyz(g.named('st_station_t', 'FLOAT'), 0., 0.), orient.inputs['Position'])
    table = orient.outputs['Geometry']
    return table, rows, valid
